// Podgrab minnevakt: read-only. Leser container-minne fra Hermes-eksportøren (Komodo-stats), ingen hemmeligheter.
// Varsler via homelab-alerts. Gjør INGEN restart/stopp; Podgrab har mem_limit 768m i compose.
const WATCH = [{ server: 'pc6-ct109-node', container: 'podgrab', warnPct: 60, critPct: 85, trendMbPerHour: 100 }];
const COOLDOWN_MS = 6 * 3600 * 1000;
const FALLBACK_LIMIT = 805306368;
const raw = String(($input.first().json.data !== undefined ? $input.first().json.data : $input.first().json) || '');
const sd = $getWorkflowStaticData('global');
sd.mem = sd.mem || {};
const now = Date.now();
const out = [];
const metric = (name, srv, ctr) => {
  const re = new RegExp('^' + name + '\\{server="' + srv + '",container="' + ctr + '"\\} ([0-9.eE+]+)$', 'm');
  const m = raw.match(re);
  return m ? Number(m[1]) : null;
};
for (const w of WATCH) {
  const key = w.server + '/' + w.container;
  const st = sd.mem[key] = sd.mem[key] || { hist: [], level: 'ok', notified: {}, missing: 0 };
  const usage = metric('komodo_container_mem_usage_bytes', w.server, w.container);
  const limit = metric('komodo_container_mem_limit_bytes', w.server, w.container) || FALLBACK_LIMIT;
  const mb = (b) => Math.round(b / 1048576);
  const send = (type, title, text) => {
    const last = Number(st.notified[type] || 0);
    if (now - last < COOLDOWN_MS && type !== 'recovered') return;
    st.notified[type] = now;
    out.push({ json: { username: 'Podgrab minnevakt', text: title, attachments: [{ title, text }] } });
  };
  if (usage === null) {
    st.missing += 1;
    if (st.missing === 3) send('missing', 'Podgrab minnevakt: måling mangler',
      'Fant ikke komodo_container_mem_usage_bytes for ' + key + ' på http://10.0.0.135:9120/metrics i 3 kjøringer på rad (30 min). Sjekk homelab-metrics.service og Komodo.');
    continue;
  }
  st.missing = 0;
  const pct = usage / limit * 100;
  const prev = st.hist.length ? st.hist[st.hist.length - 1] : null;
  st.hist.push({ t: now, u: usage });
  st.hist = st.hist.filter((h) => now - h.t <= 3 * 3600 * 1000).slice(-24);
  // Startet på nytt etter å ha vært nær taket (OOM-kill / restart)?
  if (prev && prev.u / limit * 100 >= 70 && pct < 30) {
    send('restart', 'Podgrab er trolig startet på nytt (minnetak nådd)',
      key + ': forrige måling ' + mb(prev.u) + ' MiB, nå ' + mb(usage) + ' MiB av ' + mb(limit) + ' MiB. Lekkasje i Podgrab; containeren startet selv på nytt (restart: unless-stopped).');
  }
  // Trend: >trendMbPerHour MiB/time over minst 45 min og 6 prøver
  let trend = false, perHour = 0;
  if (st.hist.length >= 6) {
    const a = st.hist[0], b = st.hist[st.hist.length - 1];
    const hrs = (b.t - a.t) / 3600000;
    if (hrs >= 0.75) { perHour = (b.u - a.u) / 1048576 / hrs; trend = perHour > w.trendMbPerHour && pct > 25; }
  }
  const twoHigh = prev && prev.u / limit * 100 >= w.warnPct && pct >= w.warnPct;
  let level = 'ok';
  if (pct >= w.critPct) level = 'crit';
  else if (twoHigh || trend) level = 'warn';
  if (level === 'crit') send('crit', 'Podgrab nær minnetaket: ' + Math.round(pct) + ' %',
    key + ' bruker ' + mb(usage) + ' av ' + mb(limit) + ' MiB. Rask restart/OOM er nær. Ingen automatisk handling er gjort.');
  else if (level === 'warn') send('warn', 'Podgrab-minne vokser (' + Math.round(pct) + ' %)',
    key + ' bruker ' + mb(usage) + ' av ' + mb(limit) + ' MiB' + (trend ? ' (≈' + Math.round(perHour) + ' MiB/time)' : '') + '. Mulig lekkasje. Ingen automatisk handling er gjort.');
  if (level === 'ok' && st.level !== 'ok') {
    send('recovered', 'Podgrab-minne tilbake til normalt', key + ' bruker nå ' + mb(usage) + ' MiB (' + Math.round(pct) + ' %).');
  }
  st.level = level;
}
return out;
